// This file was generated by Prisma and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import { defineConfig } from "prisma/config";
import "dotenv/config";

/**
 * Bun/Node 프로세스의 환경 변수 저장소.
 */
const env = process.env;

/**
 * 지정한 키의 환경 변수 값을 가져오며, 없으면 예외를 던집니다.
 */
const requireEnv = (key: string): string => {
  const value = env[key];
  if (!value) {
    throw new Error(`환경 변수 ${key}이(가) 설정되어 있지 않습니다.`);
  }
  return value;
};

/**
 * 문자열로 된 포트 번호를 정수로 파싱하며 유효하지 않으면 예외를 던집니다.
 */
const parsePort = (value: string): number => {
  const port = Number(value);
  if (!Number.isFinite(port) || port <= 0) {
    throw new Error(`유효하지 않은 포트 번호: ${value}`);
  }
  return port;
};

/**
 * MySQL 데이터베이스 연결 문자열을 생성합니다.
 */
const buildConnectionString = (params: {
  host: string;
  port: number;
  database: string;
  user: string;
  password: string;
}): string => {
  const { host, port, database, user, password } = params;
  return `mysql://${user}:${password}@${host}:${port}/${database}`;
};

/**
 * Prisma가 사용할 실제 연결 문자열.
 */
const databaseUrl =
  env.DATABASE_URL ??
  buildConnectionString({
    user: requireEnv("DATABASE_USER"),
    password: requireEnv("DATABASE_PASSWORD"),
    host: requireEnv("DATABASE_HOST"),
    port: parsePort(requireEnv("DATABASE_PORT")),
    database: requireEnv("DATABASE_NAME"),
  });

export default defineConfig({
  datasource: {
    url: databaseUrl,
  },
});
